package me.pikanote.companion;
import android.content.*;import android.bluetooth.*;import org.json.*;import java.io.*;
final class DeviceLifecycle{
 static boolean paired(Store s){synchronized(s){return !s.state.optString("device").isEmpty();}}
 static void forget(Context context)throws Exception{
 PikaService service=PikaService.instance;if(service==null||!service.ble.online)throw new IOException("Wake Pika and wait for connection before forgetting it");
 MainActivity activity=MainActivity.active;if(activity!=null&&(activity.backupPreparing||activity.recorder!=null&&activity.recorder.active()))throw new IOException("Finish recording or backup before forgetting Pika");
 synchronized(service){if(service.syncing||service.voiceBusy||service.ble.deviceBusy||PhoneAsk.running.get())throw new IOException("Wait until the current action and synchronization finish");service.maintenance=true;}
 try{Store store=Store.get(context);String serial=store.state.optString("deviceSerial");if(serial.isEmpty())throw new IOException("Update and connect Pika before changing ownership");JSONObject intent; synchronized(store){intent=store.state.optJSONObject("forgetIntent");if(intent==null)intent=new JSONObject().put("serial",serial).put("receipt",java.util.UUID.randomUUID().toString()).put("address",service.ble.address);if(!intent.optString("serial").equals(serial))throw new IOException("Another ownership reset is pending");store.state.put("forgetIntent",intent);store.save();}
 BleTransport.Reply reply=service.ble.rpc("/api/manager/settings","POST",new JSONObject().put("action","forgetOwner").put("confirmed",true).put("serial",serial).put("receipt",intent.getString("receipt")).toString(),null);
 if(reply.status>=400)throw new IOException(reply.json().optString("error","Pika refused to forget its owner"));if(!reply.json().optBoolean("resetScheduled"))throw new IOException("Pika reset was not confirmed; phone data kept");finishForget(context);
 }catch(Exception error){service.maintenance=false;throw error;}
 }
 static boolean receiptMatches(Store store,JSONObject hello){JSONObject intent=store.state.optJSONObject("forgetIntent");return intent!=null&&intent.optString("serial").matches("PN-[A-F0-9]{6}")&&intent.optString("receipt").matches("[a-f0-9-]{36}")&&!hello.optBoolean("ownerBound")&&intent.optString("serial").equals(hello.optString("serial"))&&intent.optString("receipt").equals(hello.optString("forgetReceipt"));}
 static void finishForget(Context context)throws Exception{Store store=Store.get(context);String address=store.state.optString("device");PikaService service=PikaService.instance;if(service!=null){service.maintenance=true;service.ble.closed=true;service.ble.close();context.stopService(new Intent(context,PikaService.class));}boolean removed=true;try{BluetoothManager manager=context.getSystemService(BluetoothManager.class);if(!address.isEmpty()){BluetoothDevice device=manager.getAdapter().getRemoteDevice(address);if(device.getBondState()!=BluetoothDevice.BOND_NONE)removed=Boolean.TRUE.equals(device.getClass().getMethod("removeBond").invoke(device));}}catch(Exception unsupported){removed=false;}Store.erase(context);MainActivity activity=MainActivity.active;final boolean unpaired=removed;if(activity!=null)activity.runOnUiThread(()->{activity.web.clearCache(true);activity.web.clearHistory();android.webkit.WebStorage.getInstance().deleteAllData();android.webkit.CookieManager.getInstance().removeAllCookies(null);activity.unlocked=true;activity.lastLibraryVersion="";activity.lastPhoneConnected=null;activity.lastDeviceTelemetry="";activity.web.loadUrl("https://pika.local/");if(!unpaired)activity.show("Pika is reset. If Android retains its old Bluetooth entry, forget it in Bluetooth settings.");});}
}
